Strategy.Code:
using System;
using System.Collections.Generic;
using System.Text;
using System.Drawing;
using WealthLab;
using WealthLab.Indicators;
using WealthLab.Rules;

namespace WealthLab.Strategies
{
	public class DogsOfTheDow : WealthScript, IComparer<YieldHolder>
	{
		private const string _item = "dividend"; 
		private TimeSpan _oneYear = new TimeSpan(365, 0, 0, 0);
		private StrategyParameter _numberOfDogs;

		public DogsOfTheDow()
		{
			_numberOfDogs = CreateParameter("Dogs", 10, 2, 20, 1);
		}			

		/* Returns the dividend yield calculated by summing the previous year's per share dividends 
		   and dividing by current share price */ 
		private YieldHolder YieldNow(int bar, string symbol)
		{					
			SetContext(symbol, true);
			YieldHolder holder = new YieldHolder();
			holder.symbol = symbol;
			if (Bars.FirstActualBar > bar)
			{
				holder.yld = 0d;
				RestoreContext();
				return holder;
			}

			IList<FundamentalItem> fList = FundamentalDataItems(_item);
			DateTime yearAgo = Date[bar] - _oneYear;
			double divsPerShare = 0d;

			foreach (FundamentalItem fi in fList)
			{
				if (fi.Date > yearAgo && fi.Date <= Date[bar])
				{	
					if (fi.Bar < 0) continue;
					if (100 * fi.Value / Close[fi.Bar] < 4)		// large one-time cash distribution filter (4% of share price)
						divsPerShare += fi.Value;
				}
			}
			holder.yld = 100 * (divsPerShare / Close[bar]);
			RestoreContext();
			return holder;
		}


		protected override void Execute()
		{			
			int number = _numberOfDogs.ValueInt;
			List<YieldHolder> list = new List<YieldHolder>();
			ClearDebug();
			PrintDebug("Year\tAvg Yield %");

			for(int bar = 1; bar < Bars.Count; bar++)
			{
				DateTime barDate = Date[bar];		
				bool isFriday = barDate.DayOfWeek == DayOfWeek.Friday;
				int day = barDate.Day;

				/* Do the processing on the last trading day of the year */
				if ( (barDate.Month == 12) & ((day == 31) || (isFriday & (day >= 29)))
					// || (bar == Bars.Count - 1)	// To see trades as of "today", uncomment, Compile/Run
					)
				{					
					PrintStatusBar( "Processing: " + barDate.Year.ToString()  );
					/* Load the list with the current yields and sort. Highest yields are at the end of the list. */
					list.Clear();
					double summ = 0d;
					foreach(string symbol in DataSetSymbols)
					{						
						if (Bars.FirstActualBar < bar)
						{
							YieldHolder yy = YieldNow(bar, symbol);
							list.Add(yy);
							summ += yy.yld;
							//PrintDebug(symbol + "\t" + yy.yld.ToString("0.00"));
						}						
					}
					double avgYield = summ / DataSetSymbols.Count;
					PrintDebug(Date[bar].Date.Year + "\t" + avgYield.ToString("0.0"));
					list.Sort(this);

					//remove the lowest yields from the list, leaving the specified number of Dogs
					int c = list.Count;
					for(int i = 1; i <= c - number; i++)
						list.RemoveAt(0);

					// sell all Positions to adjst for equal dollar size Positions and to reinvest dividends
					SellAtMarket(bar+1, Position.AllPositions);

					foreach(YieldHolder holder in list)
					{
						SetContext(holder.symbol, true);
						//BuyAtMarket(bar + 1, "% Yield: " + holder.yld.ToString("0.00"));
						BuyAtMarket(bar + 1, holder.yld.ToString("0.00"));
						RestoreContext();
					}
				}
			}
			PrintStatusBar("Complete!");
		}
		public int Compare(YieldHolder item1, YieldHolder item2)
		{
			return item1.yld.CompareTo(item2.yld);
		}
	}
	public class YieldHolder
	{
		internal string symbol;
		internal double yld;
	}	
}
